class Solution {
public:
    vector<int> findSubtreeSizes(vector<int>& parent, string s) {
        int n = parent.size();
        vector<vector<int>> adj(n);
        for (int i = 1; i < n; ++i) {
            adj[parent[i]].push_back(i);
        }

        vector<int> new_parent = parent;
        vector<int> last(26, -1);

        auto dfs_ancestor = [&](auto& self, int u) -> void {
            int ch = s[u] - 'a';
            int prev = last[ch];
            if (prev != -1 && u != 0) {
                new_parent[u] = prev;
            }
            last[ch] = u;
            for (int v : adj[u]) {
                self(self, v);
            }
            last[ch] = prev;
        };

        dfs_ancestor(dfs_ancestor, 0);

        vector<vector<int>> new_adj(n);
        for (int i = 1; i < n; ++i) {
            new_adj[new_parent[i]].push_back(i);
        }

        vector<int> ans(n, 1);
        auto dfs_size = [&](auto& self, int u) -> void {
            for (int v : new_adj[u]) {
                self(self, v);
                ans[u] += ans[v];
            }
        };

        dfs_size(dfs_size, 0);
        return ans;
    }
};

class Solution {
    public int[] findSubtreeSizes(int[] parent, String s) {
        int n = parent.length;
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int i = 1; i < n; i++) {
            adj[parent[i]].add(i);
        }

        int[] newParent = parent.clone();
        int[] last = new int[26];
        Arrays.fill(last, -1);

        dfsAncestor(0, adj, s, last, newParent);

        List<Integer>[] newAdj = new ArrayList[n];
        for (int i = 0; i < n; i++) newAdj[i] = new ArrayList<>();
        for (int i = 1; i < n; i++) {
            newAdj[newParent[i]].add(i);
        }

        int[] ans = new int[n];
        Arrays.fill(ans, 1);
        dfsSize(0, newAdj, ans);
        return ans;
    }

    private void dfsAncestor(int u, List<Integer>[] adj, String s, int[] last, int[] newParent) {
        int ch = s.charAt(u) - 'a';
        int prev = last[ch];
        if (prev != -1 && u != 0) {
            newParent[u] = prev;
        }
        last[ch] = u;
        for (int v : adj[u]) {
            dfsAncestor(v, adj, s, last, newParent);
        }
        last[ch] = prev;
    }

    private void dfsSize(int u, List<Integer>[] adj, int[] ans) {
        for (int v : adj[u]) {
            dfsSize(v, adj, ans);
            ans[u] += ans[v];
        }
    }
}

var findSubtreeSizes = function(parent, s) {
    const n = parent.length;
    const adj = Array.from({ length: n }, () => []);
    for (let i = 1; i < n; i++) {
        adj[parent[i]].push(i);
    }

    const newParent = [...parent];
    const last = new Array(26).fill(-1);

    function dfsAncestor(u) {
        const ch = s.charCodeAt(u) - 97;
        const prev = last[ch];
        if (prev !== -1 && u !== 0) {
            newParent[u] = prev;
        }
        last[ch] = u;
        for (const v of adj[u]) {
            dfsAncestor(v);
        }
        last[ch] = prev;
    }

    dfsAncestor(0);

    const newAdj = Array.from({ length: n }, () => []);
    for (let i = 1; i < n; i++) {
        newAdj[newParent[i]].push(i);
    }

    const ans = new Array(n).fill(1);
    function dfsSize(u) {
        for (const v of newAdj[u]) {
            dfsSize(v);
            ans[u] += ans[v];
        }
    }

    dfsSize(0);
    return ans;
};
